parameters.command:
cd /tmp && python3 -I - <<'EOF'
import sys
sys.setrecursionlimit(10000)
from neo4j import GraphDatabase
drv = GraphDatabase.driver("bolt://localhost:7687", auth=("neo4j","12345678"))
with drv.session() as s:
    nodes = [r["id"] for r in s.run("MATCH (n:UndergroundStation) RETURN n.id AS id")]
    edges = [(r["a"], r["b"]) for r in s.run("MATCH (n:UndergroundStation)-[:LINK]-(m:UndergroundStation) RETURN DISTINCT n.id AS a, m.id AS b")]
drv.close()
adj = {n:set() for n in nodes}
for a,b in edges:
    if a!=b: adj[a].add(b); adj[b].add(a)
disc={}; low={}; aps=set(); t=[0]
def dfs(u,p):
    disc[u]=low[u]=t[0]; t[0]+=1; ch=0
    for v in adj[u]:
        if v==p: continue
        if v in disc: low[u]=min(low[u],disc[v])
        else:
            ch+=1; dfs(v,u); low[u]=min(low[u],low[v])
            if p is not None and low[v]>=disc[u]: aps.add(u)
    if p is None and ch>1: aps.add(u)
for n in nodes:
    if n not in disc: dfs(n,None)
print("nodes",len(nodes),"aps",len(aps))
EOF

