adj = {"Aldgate":["Liverpool Street","Tower Hill"],"Aldgate East":["Liverpool Street","Tower Hill","Whitechapel"],"Angel":["Old Street"],"Bank":["Liverpool Street","London Bridge","Moorgate","Shadwell","St. Paul's","Waterloo"],"Barbican":["Farringdon","Moorgate"],"Bermondsey":["London Bridge"],"Bethnal Green":["Liverpool Street","Mile End"],"Borough":["London Bridge"],"Bow Road":["Mile End"],"Cannon Street":["Mansion House","Monument"],"Chancery Lane":["St. Paul's"],"Embankment":["Waterloo","Westminster"],"Farringdon":["Barbican"],"Kennington":["Waterloo"],"Lambeth North":["Waterloo"],"Liverpool Street":["Aldgate East","Bank","Bethnal Green","Moorgate","Aldgate"],"London Bridge":["Bank","Borough","Bermondsey","Southwark"],"Mansion House":["Cannon Street"],"Mile End":["Bethnal Green","Bow Road","Stepney Green","Stratford"],"Monument":["Cannon Street","Tower Hill"],"Moorgate":["Bank","Barbican","Liverpool Street","Old Street"],"Old Street":["Angel","Moorgate"],"Shadwell":["Bank","Whitechapel"],"Shoreditch":["Whitechapel"],"Southwark":["London Bridge","Waterloo"],"St. Paul's":["Bank","Chancery Lane"],"Stepney Green":["Mile End","Whitechapel"],"Stratford":["Mile End"],"Tower Hill":["Aldgate East","Monument","Aldgate"],"Waterloo":["Bank","Embankment","Kennington","Lambeth North","Westminster","Southwark"],"Westminster":["Embankment","Waterloo"],"Whitechapel":["Aldgate East","Shadwell","Shoreditch","Stepney Green"]}
