parameters.command:
cd /tmp && python3 -I -c "
import sys
sys.setrecursionlimit(10000)
G={}
for l in open('/tmp/apcheck/edges.txt'):
    a,b=l.rstrip('\n').split('|'); G.setdefault(a,set()).add(b); G.setdefault(b,set()).add(a)
def ncomp(skip):
    seen={skip}; c=0
    for s in G:
        if s in seen: continue
        c+=1; st=[s]; seen.add(s)
        while st:
            u=st.pop()
            for v in G[u]:
                if v not in seen: seen.add(v); st.append(v)
    return c
base=ncomp(None)
ap=sorted(n for n in G if ncomp(n)>base)
print(len(G), sum(len(v) for v in G.values())//2, base, len(ap))
print(ap)
"

