cd /tmp && python3 -I - <<'EOF'
import os, sys
from neo4j import GraphDatabase
sys.setrecursionlimit(100000)
drv = GraphDatabase.driver(os.environ["NEO4J_URI"], auth=(os.environ["NEO4J_USERNAME"], os.environ["NEO4J_PASSWORD"]))
with drv.session() as s:
    rows = s.run("MATCH (n:UndergroundStation)-[:LINK]-(m:UndergroundStation) WHERE id(n)<id(m) RETURN DISTINCT id(n) AS a, id(m) AS b").data()
adj = {}
for r in rows:
    adj.setdefault(r['a'], []).append(r['b']); adj.setdefault(r['b'], []).append(r['a'])
disc, low, t, bridges = {}, {}, [0], []
def dfs(u, p):
    disc[u] = low[u] = t[0]; t[0] += 1
    for v in adj[u]:
        if v == p: continue
        if v not in disc:
            dfs(v, u); low[u] = min(low[u], low[v])
            if low[v] > disc[u]: bridges.append((u, v))
        else: low[u] = min(low[u], disc[v])
for n in adj:
    if n not in disc: dfs(n, -1)
print("edges", len(rows), "bridges", len(bridges))
EOF

