parameters.cypher_query:
MATCH (n:UndergroundStation)-[r:LINK]->(m:UndergroundStation)
WITH n, m, min(r.time) AS t
RETURN gds.graph.project($graph_name, n, m, {
  sourceNodeLabels: labels(n), targetNodeLabels: labels(m),
  relationshipType: 'LINK',
  relationshipProperties: {time: toFloat(t)}
})

